        )
        require(
            flat["InstanceDown"]["annotations"] == {"summary": "{{ $labels.instance }} is down"}, flat["InstanceDown"]
        )
        require(flat["job:up:count"]["labels"] == {"tier": "lab"}, flat["job:up:count"])
    elif name == "recording_rules":
        sizes = {
            "prometheus": 1,
            "alertmanager": 1,
            "blackbox_exporter": 1,
            "node": 2,
            "probe_http": 2,
            "probe_auth": 1,
            "probe_tcp": 2,
        }

        def values():
            count = {m["job"]: v for m, v in guest.query("job:up:count") if m["job"] != ICMP_JOB}
            total = {m["job"]: v for m, v in guest.query("job:up:sum") if m["job"] != ICMP_JOB}
            require(count == {j: float(n) for j, n in sizes.items()}, count)
            require(total == {j: float(n - (1 if j == "node" else 0)) for j, n in sizes.items()}, total)
            return guest.query("job:up:count")

        require(all(m["tier"] == "lab" for m, _ in poll(values, timeout=45)), "tier label")
