        require(flags["web.route-prefix"] == "/", flags["web.route-prefix"])
        require(flags["web.external-url"] == f"https://{HOST}/prometheus/", flags["web.external-url"])
        require(flags["web.enable-lifecycle"] == "false", flags["web.enable-lifecycle"])
